import * as z from "zod/v4";
import { has } from "../../../channels/slack/agentic-posted.js";
import { MAX_UPDATE_CHARS } from "../../../channels/slack/agentic-signals.js";
import { defineTool } from "../../../tools.js";
const INVALID_ARGUMENTS_MESSAGE = "edit-message needs a ts this turn posted and a non-empty message.";
const FOREIGN_TS = "ts is not a message this turn posted";
const editMessage = defineTool({
    description: [
        "Correct a fact on a message this turn already posted (wrong number, wrong link).",
        "ts is the one post-update returned. Not a rewrite of the reply.",
        "The channel watching this turn applies the edit.",
    ].join(" "),
    inputSchema: z.object({
        ts: z.string().trim().min(1, INVALID_ARGUMENTS_MESSAGE),
        message: z
            .string({ error: INVALID_ARGUMENTS_MESSAGE })
            .min(1, INVALID_ARGUMENTS_MESSAGE)
            .superRefine((message, ctx) => {
            if (message.length > MAX_UPDATE_CHARS) {
                ctx.addIssue({
                    code: "custom",
                    message: `size (${message.length}) is more than ${MAX_UPDATE_CHARS}-character limit. drop what the reader would not act on and try again`,
                });
            }
        }),
    }),
    execute: ({ ts, message }, ctx) => {
        if (!has(ctx.session.id, ts)) {
            return FOREIGN_TS;
        }
        return { ts, message };
    },
});
export default editMessage;
